@startuml

class Boeing {
  + Name : string
}

class Employee {
  + Name : string
}

class Salesperson extends Employee {
}

class AirlineCompany {
  + Name : string
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + NegotiatedPrice : double
  + OptionsAndCustomizations : string
  + DeliveryDate : date
}

class Airplane {
  + Model : string
}

Boeing "1" -- "*" Contract : manages
Boeing "1" -- "*" Airplane : builds
Boeing "1" -- "*" Employee : employs

Contract "1" -- "1..*" Acquisition : consists of
Contract "1" -- "1" Salesperson : managed by
Contract "0..*" -- "1" Salesperson : assigned to

Acquisition "1" -- "1" Airplane : involves
Acquisition "1" -- "1" AirlineCompany : for

AirlineCompany "0..1" -- "0..1" AirlineCompany : mother-daughter relationship

@enduml

